from __future__ import annotations

from .sqlite_store import SQLiteIncidentStore


class EscalationWorker:
    """Runs the claim-and-complete escalation cycle against a store.

    The worker claims a single overdue incident and immediately completes the
    escalation in :meth:`run_once`. :meth:`run_until_idle` repeats that cycle
    until no overdue incident remains (or the optional cap is reached).
    """

    def __init__(self, store: SQLiteIncidentStore, worker_id: str) -> None:
        self.store = store
        self.worker_id = worker_id

    def run_once(self, now: float | None = None) -> object | None:
        claimed = self.store.claim_due_escalation(self.worker_id, now=now)
        if claimed is None:
            return None
        return self.store.complete_escalation(claimed.id, self.worker_id, now=now)

    def run_until_idle(
        self, max_incidents: int | None = None, now: float | None = None
    ) -> int:
        processed = 0
        while True:
            if max_incidents is not None and processed >= max_incidents:
                break
            result = self.run_once(now=now)
            if result is None:
                break
            processed += 1
        return processed

