"""Standard-library HTTP server for the incident operations interface."""

from __future__ import annotations

import json
from dataclasses import asdict
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import parse_qs, urlparse

from .errors import (
    IncidentNotFoundError,
    InvalidTransitionError,
    VersionConflictError,
)
from .escalation import EscalationWorker
from .models import Incident, IncidentStatus, Severity
from .sqlite_store import SQLiteIncidentStore

STATIC_DIR = Path(__file__).with_name("static")


def _enum(value: object) -> object:
    if hasattr(value, "value"):
        return value.value
    return value


def incident_to_json(incident: Incident) -> dict:
    return asdict(incident, dict_factory=lambda items: {k: _enum(v) for k, v in items})


def create_server(
    store: SQLiteIncidentStore,
    host: str = "127.0.0.1",
    port: int = 8080,
) -> ThreadingHTTPServer:
    """Construct and bind a server without starting its request loop.

    The store must be a :class:`SQLiteIncidentStore`. State is durable across
    server restarts because the store reads and writes the database file.
    """

    class Handler(BaseHTTPRequestHandler):
        server_version = "IncidentOps/1.0"

        def do_GET(self) -> None:
            parsed = urlparse(self.path)
            path = parsed.path
            query = parse_qs(parsed.query)
            if path == "/" or path == "/index.html":
                self._file("index.html", "text/html; charset=utf-8")
                return
            if path == "/app.js":
                self._file("app.js", "text/javascript; charset=utf-8")
                return
            if path == "/styles.css":
                self._file("styles.css", "text/css; charset=utf-8")
                return
            if path == "/api/incidents":
                incidents = store.list(
                    status=_first(query, "status"),
                    severity=_first(query, "severity"),
                    owner=_first(query, "owner"),
                )
                self._json(200, [incident_to_json(i) for i in incidents])
                return
            if path == "/api/summary":
                self._json(200, _summary(store))
                return
            if path.startswith("/api/incidents/"):
                incident_id = path[len("/api/incidents/"):]
                incident = store.get(incident_id)
                if incident is None:
                    self._json(404, {"error": f"incident {incident_id} not found"})
                    return
                events = [asdict(e, dict_factory=_event_dict) for e in store.events(incident_id)]
                payload = incident_to_json(incident)
                payload["events"] = events
                self._json(200, payload)
                return
            self._json(404, {"error": "not found"})

        def do_POST(self) -> None:
            parsed = urlparse(self.path)
            path = parsed.path
            if path == "/api/alerts":
                self._handle_alert()
                return
            if path == "/api/escalations/run":
                self._handle_escalate()
                return
            self._json(404, {"error": "not found"})

        def do_PATCH(self) -> None:
            parsed = urlparse(self.path)
            path = parsed.path
            if not path.startswith("/api/incidents/"):
                self._json(404, {"error": "not found"})
                return
            incident_id = path[len("/api/incidents/"):]
            try:
                payload = self._body()
            except (json.JSONDecodeError, ValueError) as exc:
                self._json(400, {"error": f"invalid json: {exc}"})
                return
            if "expected_version" not in payload:
                self._json(400, {"error": "expected_version is required"})
                return
            try:
                expected_version = int(payload["expected_version"])
            except (TypeError, ValueError):
                self._json(400, {"error": "expected_version must be an integer"})
                return
            try:
                updated = store.update(
                    incident_id,
                    expected_version,
                    owner=payload.get("owner"),
                    status=payload.get("status"),
                    idempotency_key=payload.get("idempotency_key"),
                )
            except VersionConflictError as exc:
                self._json(409, {"error": str(exc)})
                return
            except IncidentNotFoundError:
                self._json(404, {"error": f"incident {incident_id} not found"})
                return
            except (InvalidTransitionError, ValueError) as exc:
                self._json(400, {"error": str(exc)})
                return
            self._json(200, incident_to_json(updated))

        def _handle_alert(self) -> None:
            try:
                payload = self._body()
            except (json.JSONDecodeError, ValueError) as exc:
                self._json(400, {"error": f"invalid json: {exc}"})
                return
            try:
                incident, created = store.ingest_alert(
                    fingerprint=payload.get("fingerprint") or "",
                    title=payload.get("title") or "",
                    severity=payload.get("severity") or "",
                    source=payload.get("source", "unknown"),
                    details=payload.get("details"),
                    idempotency_key=payload.get("idempotency_key"),
                )
            except ValueError as exc:
                self._json(400, {"error": str(exc)})
                return
            self._json(201 if created else 200, incident_to_json(incident))

        def _handle_escalate(self) -> None:
            try:
                payload = self._body(optional=True)
            except (json.JSONDecodeError, ValueError) as exc:
                self._json(400, {"error": f"invalid json: {exc}"})
                return
            payload = payload or {}
            worker_id = payload.get("worker_id") or "worker-1"
            max_incidents = payload.get("max_incidents")
            if max_incidents is not None:
                try:
                    max_incidents = int(max_incidents)
                except (TypeError, ValueError):
                    self._json(400, {"error": "max_incidents must be an integer"})
                    return
            store.recover_expired_claims()
            worker = EscalationWorker(store, worker_id)
            count = worker.run_until_idle(max_incidents=max_incidents)
            self._json(200, {"worker_id": worker_id, "escalated": count})

        def _body(self, optional: bool = False) -> dict:
            length = int(self.headers.get("Content-Length", "0") or "0")
            if length <= 0:
                if optional:
                    return {}
                raise ValueError("empty request body")
            data = self.rfile.read(length)
            return json.loads(data.decode("utf-8"))

        def _file(self, name: str, content_type: str) -> None:
            try:
                body = (STATIC_DIR / name).read_bytes()
            except FileNotFoundError:
                self._json(404, {"error": "not found"})
                return
            self.send_response(200)
            self.send_header("Content-Type", content_type)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _json(self, status: int, value: object) -> None:
            body = json.dumps(value, default=_enum).encode("utf-8")
            self.send_response(status)
            self.send_header("Content-Type", "application/json")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def log_message(self, format: str, *args: object) -> None:
            return

    return ThreadingHTTPServer((host, port), Handler)


def _first(query: dict[str, list[str]], key: str) -> str | None:
    values = query.get(key)
    return values[0] if values else None


def _event_dict(items) -> dict:
    return {k: _enum(v) for k, v in items}


def _summary(store: SQLiteIncidentStore) -> dict:
    incidents = store.list()
    by_status: dict[str, int] = {str(s): 0 for s in IncidentStatus}
    by_severity: dict[str, int] = {str(s): 0 for s in Severity}
    for inc in incidents:
        by_status[str(inc.status)] += 1
        by_severity[str(inc.severity)] += 1
    return {
        "total": len(incidents),
        "by_status": by_status,
        "by_severity": by_severity,
    }

