:root {
  --bg: #eef2f7;
  --panel: #ffffff;
  --border: #d8e0ea;
  --text: #172033;
  --muted: #5b6b82;
  --accent: #3154a5;
  --danger: #b3261e;
  --ok: #1e7d4a;
  --warn: #9a6b00;
  --shadow: 0 1px 2px rgba(23, 32, 51, 0.06);
  color: var(--text);
  background: var(--bg);
  font-family: Inter, ui-sans-serif, system-ui, sans-serif;
}

* { box-sizing: border-box; }
body { margin: 0; }

main {
  width: min(1100px, calc(100% - 24px));
  margin: 16px auto;
  display: grid;
  gap: 14px;
}

.panel {
  background: var(--panel);
  border: 1px solid var(--border);
  border-radius: 12px;
  padding: 14px;
  box-shadow: var(--shadow);
}

.app-header { text-align: left; }
.eyebrow { color: var(--accent); font-weight: 700; text-transform: uppercase; letter-spacing: .08em; margin: 0 0 4px; }
h1 { margin: 0 0 4px; font-size: 1.4rem; }
h2 { margin: 0 0 10px; font-size: 1.05rem; }
p { margin: 0; }

.alert-form, .filters { display: flex; flex-wrap: wrap; gap: 10px; align-items: end; }
.field { display: grid; gap: 4px; flex: 1 1 160px; }
.field.narrow { flex: 0 0 110px; }
input, select, button { box-sizing: border-box; min-height: 40px; padding: 8px 10px; font: inherit; border: 1px solid var(--border); border-radius: 8px; background: #fff; color: var(--text); width: 100%; }
button { border: 0; color: #fff; background: var(--accent); font-weight: 700; cursor: pointer; padding-inline: 14px; }
button:hover { filter: brightness(1.05); }
#escalate-btn { background: #6b4fa0; }

.summary-panel { padding: 12px; }
.summary-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(96px, 1fr)); gap: 8px; }
.stat { background: #f4f7fb; border: 1px solid var(--border); border-radius: 8px; padding: 8px 10px; }
.stat .label { font-size: .72rem; text-transform: uppercase; letter-spacing: .06em; color: var(--muted); }
.stat .value { font-size: 1.2rem; font-weight: 700; }

#feedback { min-height: 1.2em; font-weight: 600; color: var(--accent); }
#feedback.error { color: var(--danger); }
#feedback.ok { color: var(--ok); }

.split { display: grid; grid-template-columns: 1.1fr 1fr; gap: 14px; }
.list-panel { display: flex; flex-direction: column; }
.incident-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 8px; }

.incident-row {
  border: 1px solid var(--border);
  border-radius: 10px;
  padding: 10px;
  cursor: pointer;
  background: #fbfcfe;
  display: grid;
  grid-template-columns: 44px 1fr auto;
  align-items: center;
  gap: 10px;
}
.incident-row.selected { outline: 2px solid var(--accent); }
.incident-row.resolved { opacity: .7; }
.sev { font-weight: 700; font-size: .8rem; border-radius: 6px; padding: 4px 0; text-align: center; color: #fff; }
.sev-P1 { background: var(--danger); }
.sev-P2 { background: #c2410c; }
.sev-P3 { background: var(--warn); }
.sev-P4 { background: #3f6212; }
.row-main { min-width: 0; }
.row-main .title { font-weight: 600; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.row-main .meta { font-size: .78rem; color: var(--muted); }
.badge { font-size: .72rem; padding: 3px 8px; border-radius: 999px; border: 1px solid var(--border); background: #eef2f7; }
.badge.open { color: var(--warn); }
.badge.acknowledged { color: var(--accent); }
.badge.resolved { color: var(--ok); }

.detail-panel .placeholder { color: var(--muted); }
.detail-head { display: flex; flex-wrap: wrap; justify-content: space-between; gap: 8px; }
.detail-head h3 { margin: 0; font-size: 1.05rem; }
.detail-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 6px 12px; margin: 10px 0; font-size: .85rem; }
.detail-grid .k { color: var(--muted); }
.actions { display: flex; flex-wrap: wrap; gap: 8px; align-items: end; margin: 10px 0; }
.owner-input { flex: 1 1 140px; }
.actions button { flex: 0 0 auto; }
.btn-ack { background: #2c7a7b; }
.btn-resolve { background: var(--ok); }

.timeline { list-style: none; margin: 8px 0 0; padding: 0; display: grid; gap: 6px; }
.timeline li { border-left: 3px solid var(--accent); padding: 6px 10px; background: #f4f7fb; border-radius: 0 6px 6px 0; font-size: .82rem; }
.timeline .t-type { font-weight: 700; }
.timeline .t-time { color: var(--muted); font-size: .74rem; }

@media (max-width: 720px) {
  .split { grid-template-columns: 1fr; }
  .alert-form, .filters { flex-direction: column; align-items: stretch; }
  .field, .field.narrow { flex: 1 1 auto; }
  .detail-grid { grid-template-columns: 1fr; }
  main { margin: 8px auto; }
  .incident-row { grid-template-columns: 36px 1fr; }
  .incident-row .badge { grid-column: 2; justify-self: start; }
}

