  detail: document.getElementById("incident-detail"),
  escalateBtn: document.getElementById("escalate-btn"),
};

function setFeedback(message, kind) {
  state.feedback = message || "";
  el.feedback.textContent = state.feedback;
  el.feedback.className = kind || "";
}

async function fetchJSON(url, options) {
  const response = await fetch(url, options);
  let data = null;
  const text = await response.text();
  if (text) {
    try { data = JSON.parse(text); } catch (e) { data = null; }
  }
  return { ok: response.ok, status: response.status, data };
}

async function refresh() {
  const params = new URLSearchParams();
  if (state.filters.status) params.set("status", state.filters.status);
  if (state.filters.severity) params.set("severity", state.filters.severity);
  if (state.filters.owner) params.set("owner", state.filters.owner);
  const { ok, data } = await fetchJSON(`/api/incidents?${params.toString()}`);
  if (!ok) {
    setFeedback("Could not load incidents", "error");
    return state.incidents = [];
  }
  state.incidents = data;
  renderSummary();
  renderList();
  if (state.selectedId) {
    await loadDetail(state.selectedId);
  }
  return state.incidents;
}

async function loadSummary() {
  const { ok, data } = await fetchJSON("/api/summary");
  if (ok) state.summary = data;
  renderSummary();
}

async function loadDetail(id) {
  const { ok, status, data } = await fetchJSON(`/api/incidents/${encodeURIComponent(id)}`);
  if (!ok) {
    state.selected = null;
    state.selectedId = null;
    setFeedback(`Incident ${id} not found`, "error");
    renderDetail();
    return;
  }
  state.selected = data;
  state.selectedId = id;
  renderList();
  renderDetail();
}

async function selectIncident(id) {
  await loadDetail(id);
}

function getState() {
  return {
    filters: { ...state.filters },
    selectedIncidentId: state.selectedId,
    incidents: state.incidents,
    feedback: state.feedback,
  };
}

function renderSummary() {
  const summary = state.summary || { total: state.incidents.length, by_status: {}, by_severity: {} };
  const items = [
    { label: "Total", value: summary.total ?? state.incidents.length },
    { label: "Open", value: summary.by_status?.open ?? 0 },
    { label: "Ack", value: summary.by_status?.acknowledged ?? 0 },
    { label: "Resolved", value: summary.by_status?.resolved ?? 0 },
    { label: "P1", value: summary.by_severity?.P1 ?? 0 },
    { label: "P2", value: summary.by_severity?.P2 ?? 0 },
    { label: "P3", value: summary.by_severity?.P3 ?? 0 },
    { label: "P4", value: summary.by_severity?.P4 ?? 0 },
  ];
  el.summaryGrid.replaceChildren(...items.map((item) => {
    const node = document.createElement("div");
    node.className = "stat";
    const label = document.createElement("div"); label.className = "label"; label.textContent = item.label;
    const value = document.createElement("div"); value.className = "value"; value.textContent = String(item.value);
    node.append(label, value);
    return node;
  }));
}

function renderList() {
  el.list.replaceChildren(...state.incidents.map((incident) => {
    const row = document.createElement("li");
    row.className = `incident-row sev-${incident.severity}`;
    row.dataset.testid = "incident-row";
    row.dataset.id = incident.id;
    if (incident.id === state.selectedId) row.classList.add("selected");
    if (incident.status === "resolved") row.classList.add("resolved");

    const sev = document.createElement("span");
    sev.className = `sev sev-${incident.severity}`;
    sev.textContent = incident.severity;

    const main = document.createElement("div");
    main.className = "row-main";
    const title = document.createElement("div"); title.className = "title"; title.textContent = incident.title;
    const meta = document.createElement("div");
    meta.className = "meta";
    meta.textContent = `${incident.fingerprint || "-"}  ·  alerts ${incident.alert_count}  ·  v${incident.version}  ·  L${incident.escalation_level}`;
    main.append(title, meta);

    const badge = document.createElement("span");
    badge.className = `badge ${incident.status}`;
    badge.textContent = incident.status;
    badge.dataset.testid = "status-badge";

    row.append(sev, main, badge);
    row.addEventListener("click", () => selectIncident(incident.id));
    return row;
  }));
}

function renderDetail() {
  const incident = state.selected;
  if (!incident) {
    el.detail.replaceChildren(placeholder());
    return;
  }
  const root = document.createElement("div");
  root.dataset.testid = "incident-detail";

  const head = document.createElement("div");
  head.className = "detail-head";
  const h = document.createElement("h3"); h.textContent = incident.title;
  const badge = document.createElement("span"); badge.className = `badge ${incident.status}`; badge.textContent = incident.status;
  head.append(h, badge);

  const grid = document.createElement("div");
  grid.className = "detail-grid";
  const rows = [
    ["ID", incident.id],
    ["Fingerprint", incident.fingerprint || "-"],
    ["Severity", incident.severity],
    ["Status", incident.status],
    ["Owner", incident.owner || "unassigned"],
    ["Alert count", incident.alert_count],
    ["Version", incident.version],
    ["Escalation level", incident.escalation_level],
    ["Created", fmtTime(incident.created_at)],
    ["Updated", fmtTime(incident.updated_at)],
    ["SLA deadline", fmtTime(incident.sla_deadline)],
  ];
  for (const [k, v] of rows) {
    const key = document.createElement("div"); key.className = "k"; key.textContent = k;
    const val = document.createElement("div"); val.className = "v"; val.textContent = String(v);
    grid.append(key, val);
  }

  const actions = document.createElement("div");
  actions.className = "actions";
  const ownerInput = document.createElement("input");
  ownerInput.className = "owner-input";
  ownerInput.dataset.testid = "owner-input";
  ownerInput.placeholder = "Owner";
  ownerInput.value = incident.owner || "";
  const ackBtn = document.createElement("button");
  ackBtn.dataset.testid = "acknowledge-action";
  ackBtn.className = "btn-ack";
  ackBtn.textContent = "Acknowledge";
  ackBtn.disabled = incident.status !== "open";
  const resolveBtn = document.createElement("button");
  resolveBtn.dataset.testid = "resolve-action";
  resolveBtn.className = "btn-resolve";
  resolveBtn.textContent = "Resolve";
  resolveBtn.disabled = incident.status === "resolved";
  actions.append(ownerInput, ackBtn, resolveBtn);

  ackBtn.addEventListener("click", () => patchIncident({ owner: ownerInput.value, status: "acknowledged" }));
  resolveBtn.addEventListener("click", () => patchIncident({ owner: ownerInput.value, status: "resolved" }));

  const timelineTitle = document.createElement("h2");
  timelineTitle.textContent = "Audit timeline";
  const timeline = document.createElement("ol");
  timeline.className = "timeline";
  timeline.dataset.testid = "timeline";
  const events = incident.events || [];
  timeline.replaceChildren(...events.map((ev) => {
    const li = document.createElement("li");
    const t = document.createElement("div"); t.className = "t-type"; t.textContent = ev.type;
    const time = document.createElement("div"); time.className = "t-time"; time.textContent = fmtTime(ev.timestamp);
    const det = document.createElement("div"); det.textContent = JSON.stringify(ev.details || {});
    li.append(t, time, det);
    return li;
  }));

  root.append(head, grid, actions, timelineTitle, timeline);
  el.detail.replaceChildren(root);
}

function placeholder() {
  const p = document.createElement("p");
  p.className = "placeholder";
  p.textContent = "Select an incident to see details.";
  return p;
}

async function patchIncident(changes) {
  if (!state.selected) return;
  const body = { expected_version: state.selected.version, ...changes };
  const { ok, status, data } = await fetchJSON(
    `/api/incidents/${encodeURIComponent(state.selected.id)}`,
    { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }
  );
  if (ok) {
    state.selected = data;
    setFeedback("Incident updated", "ok");
  } else {
    setFeedback(data?.error || `Update failed (${status})`, "error");
  }
  await refresh();
  await loadSummary();
}

function fmtTime(ts) {
  if (!ts) return "-";
  const d = new Date(ts * 1000);
  if (Number.isNaN(d.getTime())) return String(ts);
  return d.toLocaleString();
}

el.alertForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const data = new FormData(el.alertForm);
  const payload = Object.fromEntries(data);
  const { ok, status, data: result } = await fetchJSON("/api/alerts", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (ok) {
    setFeedback(status === 201 ? "Incident created" : "Duplicate alert merged", "ok");
    el.alertForm.reset();
  } else {
    setFeedback(result?.error || "Could not ingest alert", "error");
  }
  await refresh();
  await loadSummary();
});

