});
el.severityFilter.addEventListener("change", () => {
  state.filters.severity = el.severityFilter.value;
  refresh();
});
el.escalateBtn.addEventListener("click", async () => {
  const { ok, data } = await fetchJSON("/api/escalations/run", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ worker_id: "browser" }),
  });
  if (ok) {
    setFeedback(`Escalated ${data.escalated} incident(s)`, "ok");
  } else {
    setFeedback("Escalation run failed", "error");
  }
  await refresh();
  await loadSummary();
});

