"use strict";

const state = {
  incidents: [],
  selectedId: null,
  selected: null,
  feedback: "",
  filters: { status: "", severity: "", owner: "" },
};

const el = {
  app: document.getElementById("incident-app"),
  summaryGrid: document.getElementById("summary-grid"),
  alertForm: document.getElementById("alert-form"),
  statusFilter: document.getElementById("status-filter"),
  severityFilter: document.getElementById("severity-filter"),
  feedback: document.getElementById("feedback"),
  list: document.getElementById("incident-list"),
  detail: document.getElementById("incident-detail"),
  escalateBtn: document.getElementById("escalate-btn"),
};

function setFeedback(message, kind) {
  state.feedback = message || "";
  el.feedback.textContent = state.feedback;
  el.feedback.className = kind || "";
}

async function fetchJSON(url, options) {
  const response = await fetch(url, options);
  let data = null;
  const text = await response.text();
  if (text) {
    try { data = JSON.parse(text); } catch (e) { data = null; }
  }
  return { ok: response.ok, status: response.status, data };
}

async function refresh() {
  const params = new URLSearchParams();
  if (state.filters.status) params.set("status", state.filters.status);
  if (state.filters.severity) params.set("severity", state.filters.severity);
  if (state.filters.owner) params.set("owner", state.filters.owner);
  const { ok, data } = await fetchJSON(`/api/incidents?${params.toString()}`);
  if (!ok) {
    setFeedback("Could not load incidents", "error");
    return state.incidents = [];
  }
  state.incidents = data;
  renderSummary();
  renderList();
  if (state.selectedId) {
    await loadDetail(state.selectedId);
  }
  return state.incidents;
}

async function loadSummary() {
  const { ok, data } = await fetchJSON("/api/summary");
  if (ok) state.summary = data;
  renderSummary();
}

async function loadDetail(id) {
  const { ok, status, data } = await fetchJSON(`/api/incidents/${encodeURIComponent(id)}`);
  if (!ok) {
    state.selected = null;
    state.selectedId = null;
    setFeedback(`Incident ${id} not found`, "error");
    renderDetail();
    return;
  }
  state.selected = data;
  state.selectedId = id;
  renderList();
  renderDetail();
}

async function selectIncident(id) {
  await loadDetail(id);
}

function getState() {
  return {
    filters: { ...state.filters },
    selectedIncidentId: state.selectedId,
    incidents: state.incidents,
    feedback: state.feedback,
  };
}

function renderSummary() {
  const summary = state.summary || { total: state.incidents.length, by_status: {}, by_severity: {} };
  const items = [
    { label: "Total", value: summary.total ?? state.incidents.length },
    { label: "Open", value: summary.by_status?.open ?? 0 },
    { label: "Ack", value: summary.by_status?.acknowledged ?? 0 },
    { label: "Resolved", value: summary.by_status?.resolved ?? 0 },
    { label: "P1", value: summary.by_severity?.P1 ?? 0 },
    { label: "P2", value: summary.by_severity?.P2 ?? 0 },
    { label: "P3", value: summary.by_severity?.P3 ?? 0 },
    { label: "P4", value: summary.by_severity?.P4 ?? 0 },
