const ids = ["incident-app","summary-grid","alert-form","status-filter","severity-filter","feedback","incident-list","incident-detail","escalate-btn"];
for (const id of ids) el(id);

// Summary panel root used by data-testid summary is #summary in html, but app uses summaryGrid.
el("summary");

// Fake form fields for the alert form
const form = elements["alert-form"];
form.elements = {};
for (const n of ["title","fingerprint","severity","source"]) { const f=new Element("input"); f.name=n; f.value=n==="severity"?"P2":(n==="source"?"unknown":`val-${n}`); form.elements[n]=f; }

class FormData {
  constructor(f){ this.entries = []; for (const n of ["title","fingerprint","severity","source"]) this.entries.push([n, f.elements[n].value]); }
  *[Symbol.iterator](){ yield* this.entries; }
}

// ---- canned API responses ----
const incidents = [
  {id:"inc-1", title:"DB down", severity:"P1", status:"open", owner:null, fingerprint:"fp-1", alert_count:2, version:1, escalation_level:0, created_at:100, updated_at:110, sla_deadline:160},
  {id:"inc-2", title:"API slow", severity:"P2", status:"acknowledged", owner:"rajiv", fingerprint:"fp-2", alert_count:1, version:2, escalation_level:0, created_at:100, updated_at:120, sla_deadline:400},
];
const summary = { total:2, by_status:{open:1,acknowledged:1,resolved:0}, by_severity:{P1:1,P2:1,P3:0,P4:0} };
const detail = {...incidents[0], events:[
  {id:1, incident_id:"inc-1", type:"created", timestamp:100, details:{fingerprint:"fp-1"}},
  {id:2, incident_id:"inc-1", type:"duplicate_alert", timestamp:110, details:{alert_count:2}},
]};
function fetchJSON(url, opts){
  let body;
  if (url.startsWith("/api/incidents?")) body = incidents;
  else if (url.startsWith("/api/summary")) body = summary;
  else if (url.startsWith("/api/incidents/inc-1")) body = detail;
  else if (url.startsWith("/api/incidents/inc-2")) body = {...incidents[1], events:[{id:3,incident_id:"inc-2",type:"created",timestamp:100,details:{}}]};
  else body = {};
  return Promise.resolve({ ok:true, status:200, text:()=>Promise.resolve(JSON.stringify(body)) });
}

const document = {
  getElementById: (id)=> elements[id] || (elements[id]=el(id)),
  querySelector: (sel)=> { if (sel === "#incident-app") return elements["incident-app"]; if (sel==="#incident-list") return elements["incident-list"]; return null; },
  createElement: (tag)=> new Element(tag),
};

const sandbox = {
  window: {},
  document,
  FormData,
  fetch: fetchJSON,
  URLSearchParams: class { constructor(){ this.p={}; } set(k,v){this.p[k]=v;} toString(){ const parts=[]; for(const k in this.p) parts.push(`${k}=${this.p[k]}`); return parts.join("&"); } },
  JSON, Date, Number, Math, console,
  Promise, setTimeout,
};
sandbox.window.incidentOps = null;
sandbox.self = sandbox.window;
vm.createContext(sandbox);

const appJs = fs.readFileSync(path.join("incident_ops/static/app.js"), "utf8");
vm.runInContext(appJs, sandbox, { filename: "app.js" });

(async () => {
  // The app.js IIFE already ran loadSummary/refresh; call refresh again to be sure.
  await sandbox.window.incidentOps.refresh();
  const state = sandbox.window.incidentOps.getState();
  console.log("incidents loaded:", state.incidents.length);
  console.log("filters:", JSON.stringify(state.filters));
  console.log("selectedIncidentId (initial):", state.selectedIncidentId);
  console.log("feedback:", JSON.stringify(state.feedback));
  if (state.incidents.length !== 2) throw new Error("expected 2 incidents");
  // summary rendered
  const summaryChildren = elements["summary-grid"].children.length;
  console.log("summary stat count:", summaryChildren);
  if (summaryChildren < 8) throw new Error("summary stats not rendered");
  // incident list rows
  const rows = elements["incident-list"].children;
  console.log("rows:", rows.length, "first row testid:", rows[0].dataset.testid, "sev class:", rows[0].className);
  if (rows.length !== 2 || rows[0].dataset.testid !== "incident-row") throw new Error("rows not rendered with testid");
  // select incident -> detail + timeline
  await sandbox.window.incidentOps.selectIncident("inc-1");
  const st2 = sandbox.window.incidentOps.getState();
  console.log("after select selectedId:", st2.selectedIncidentId);
  if (st2.selectedIncidentId !== "inc-1") throw new Error("select failed");
  const detailEl = elements["incident-detail"].children[0];
  const timeline = elements["incident-detail"].children[0] && [...elements["incident-detail"].children[0].children].find(c => c.dataset && c.dataset.testid === "timeline");
  console.log("detail testid:", detailEl && detailEl.dataset.testid);
  console.log("timeline present:", !!timeline, "events:", timeline ? timeline.children.length : 0);
  if (!timeline || timeline.children.length !== 2) throw new Error("timeline not rendered");
  // owner-input, acknowledge-action, resolve-action markers
  const ownerInput = [...elements["incident-detail"].children[0].children].flatMap(c=>c.children||[]).find(c=>c.dataset&&c.dataset.testid==="owner-input");
  const ack = [...elements["incident-detail"].children[0].children].flatMap(c=>c.children||[]).find(c=>c.dataset&&c.dataset.testid==="acknowledge-action");
  const resv = [...elements["incident-detail"].children[0].children].flatMap(c=>c.children||[]).find(c=>c.dataset&&c.dataset.testid==="resolve-action");
  console.log("owner-input:",!!ownerInput,"ack:",!!ack,"resolve:",!!resv);
  if (!ownerInput||!ack||!resv) throw new Error("action markers missing");
  console.log("ALL BROWSER CONTRACT CHECKS PASSED");
})().catch(e=>{ console.error("FAIL", e); process.exit(1); });
